"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[241],{80241:e=>{e.exports=JSON.parse('{"slug":"tarify-gaz-elektrichestvo-oktyabr-2026","locale":"es","title":"El gas sube un 9,6% y la electricidad dom\xe9stica un 11,3% desde el 1 de octubre de 2026","description":"Desde el 1 de octubre de 2026, la electricidad dom\xe9stica sube un 11,3% y el gas un 9,6%. C\xf3mo se compone la factura y qu\xe9 llega en julio de 2027.","blocks":[{"id":"b001","kind":"paragraph","text":"El gas y la electricidad rusos subieron el 1 de octubre de 2026. El precio mayorista de Gazprom creci\xf3 un 9,6%; la electricidad dom\xe9stica, un 11,3% para consumos de hasta 3900 kWh mensuales. Los fija el Estado con calendario y porcentaje previstos, no el mercado: son precios regulados. La subida de 2026 figuraba ya en la previsi\xf3n gubernamental del a\xf1o anterior."},{"id":"b002","kind":"paragraph","text":"La factura de gas tiene tres partes: el 80% es gas; el 15%, transporte por tuber\xedas; y el 5%, servicio comercial. Desde el 1 de octubre suben por separado: 9,6%, 11,6% y 5,1%. El total aumenta cerca del 9,7% (0,8 \xd7 9,6 + 0,15 \xd7 11,6 + 0,05 \xd7 5,1)."},{"id":"b003","kind":"paragraph","text":"La electricidad suma energ\xeda y transporte. Las redes troncales subieron un 16% y las distribuidoras un 15,2%. El precio dom\xe9stico final aumenta menos, un 11,3%, porque el transporte es solo una parte."},{"id":"b004","kind":"paragraph","text":"Por cada 1000 rublos de electricidad, la familia paga ahora 113 extra; por gas, cerca de 97. En Mosc\xfa, el kWh de un piso con cocina de gas pas\xf3 de 8 a 8,9 rublos. Con 200 kWh mensuales se pagan 1780 en lugar de 1600, unos 180 m\xe1s. Las autoridades locales aprueban las tarifas dentro de los l\xedmites del Servicio Federal Antimonopolio."},{"id":"b005","kind":"paragraph","text":"No ser\xe1 la \xfaltima subida. Desde el 1 de julio de 2027, el gas aumentar\xe1 otro 10,4%, frente al 9,1% previsto antes. Ambas actualizaciones elevan el mayorista cerca del 21% en 9 meses (1,096 \xd7 1,104). Las redes de distribuci\xf3n dom\xe9stica subir\xe1n un 17,5% en julio de 2027. El calendario habitual de julio vuelve desde 2027."},{"id":"b006","kind":"paragraph","text":"Los contadores, bombillas eficientes y aislamiento se amortizan antes con facturas altas, como una casa de calefacci\xf3n el\xe9ctrica. En un piso peque\xf1o tardan m\xe1s. Ya puede incluirse en el presupuesto la subida de julio de 2027, aunque el porcentaje se haya revisado una vez."},{"id":"b007","kind":"heading","text":"\xbfCu\xe1nto subi\xf3 el gas desde el 1 de octubre de 2026?"},{"id":"b008","kind":"paragraph","text":"El gas mayorista sube un 9,6%; el transporte de distribuci\xf3n, un 11,6%; y el servicio comercial, un 5,1%. La factura total crece aproximadamente un 9,7%."},{"id":"b009","kind":"heading","text":"\xbfCu\xe1nto subi\xf3 la electricidad desde el 1 de octubre de 2026?"},{"id":"b010","kind":"paragraph","text":"Un 11,3% para hogares de hasta 3900 kWh al mes. Las redes subieron m\xe1s, entre el 15,2 y el 16%."},{"id":"b011","kind":"heading","text":"\xbfCu\xe1ndo volver\xe1n a subir gas y electricidad?"},{"id":"b012","kind":"paragraph","text":"Desde el 1 de julio de 2027. El gas aumentar\xe1 un 10,4% y las distribuidoras dom\xe9sticas un 17,5%, aunque estas son solo una parte de la factura el\xe9ctrica."}],"sources":[{"label":"Los precios regulados de Gazprom suben un 9,6%","url":"https://www.interfax.ru/business/1119546"},{"label":"Antimonopolio actualiza el gas un 9,6% desde el 1 de octubre","url":"https://www.garant.ru/news/1947004/"},{"label":"Las redes el\xe9ctricas suben un 15,2% y la red unificada un 16%","url":"https://www.interfax.ru/russia/1119539"},{"label":"Antimonopolio comprobar\xe1 las tarifas regionales","url":"https://www.kommersant.ru/doc/8990884"},{"label":"Tarifas el\xe9ctricas de Mosc\xfa en 2026","url":"https://t-j.ru/msk-electroprices/"},{"label":"Electricidad en Mosc\xfa, 2026","url":"https://www.vesti.ru/vj/tarify-na-ehlektroehnergiyu-v-moskve"}],"sourceBodySha256":"b809a176f95ae120cd852b989f922de8a276fc4ea55fc40cff70d0caebfcadd4"}')}}]);